from pathlib import Path
import subprocess,os,time,json
r=Path(__file__).resolve().parents[2];o=Path(os.environ.get('JAGO_PROJECT_TEST_WORK',__import__('tempfile').gettempdir()))/('Library-image-text-'+time.strftime('%H%M%S'));o.mkdir()
code='''(async()=>{try{for(let i=0;i<200&&!window.appReady;i++)await new Promise(r=>setTimeout(r,100));examples();const canvas=document.createElement('canvas');canvas.width=1000;canvas.height=300;const g=canvas.getContext('2d');g.fillStyle='white';g.fillRect(0,0,1000,300);g.fillStyle='black';g.font='44px Arial';g.fillText('Jago creative tools',30,80);g.fillText('Copy these words offline',30,140);const item={id:crypto.randomUUID(),name:'OCR fixture.png',type:'image',url:canvas.toDataURL('image/png'),tags:[],size:1000};state.assets.push(item);await imageTextPreview(item.id);if(!$('imageTextTranscript').value.includes('creative'))throw Error('Recognised text missing');const spans=[...$('imageTextSurface').querySelectorAll('span')];if(spans.length<7)throw Error('Word overlays missing');const selection=window.getSelection(),range=document.createRange();range.setStart(spans[0].firstChild,0);range.setEnd(spans[2].firstChild,spans[2].textContent.length);selection.removeAllRanges();selection.addRange(range);if(selection.toString().trim()!=='Jago creative tools')throw Error('Word selection incorrect: '+selection);window.suiteTestResult={ok:true,checks:['Real offline Windows OCR reads fixture through Library bridge','Selectable words appear over the image','A selected phrase matches the recognised words']};}catch(e){window.suiteTestResult={ok:false,error:e.stack};}})();'''
(o/'probe.js').write_text(code,encoding='utf-8');env=os.environ.copy();env['JAGO_SUITE_ROOT']=str(o/'Suite');si=subprocess.STARTUPINFO();si.dwFlags=subprocess.STARTF_USESHOWWINDOW;si.wShowWindow=0
subprocess.run([str(r/'Jago-Library.exe'),'--suite-test',str(o)],env=env,startupinfo=si,timeout=60,check=True);d=json.loads((o/'result.json').read_text(encoding='utf-8-sig'));print(json.dumps({'folder':str(o),'result':d}));assert d['ok'],d
